#pragma once

#include "endweave/protocol/block.h"
#include "endweave/protocol/version.h"

#include <algorithm>
#include <bedrock/protocol/nbt.hpp>
#include <cstdint>
#include <optional>
#include <span>
#include <string_view>
#include <utility>
#include <vector>

namespace endweave {

/** The block types whose states change across one hop. Generated by tools/generate_block_states.py. */
template <int From, int To>
std::span<const BlockStateUpdate> getBlockStateUpdates();

/** The items, by name and sorted, that a hop's `From` has and its `To` has no mapping for. A hop
 * with any specialises it with `get()`, generated by tools/generate_items.py.
 * @see ViaBackwards ItemMappings. */
template <int From, int To>
struct ItemMappings {};

template <int From, int To>
concept HasItemMappings = requires { ItemMappings<From, To>::get(); };

/** Every block one hop renumbers, as its id at `From` and at `To`, sorted by the first. */
using BlockStateMappings = std::vector<std::pair<std::uint32_t, std::uint32_t>>;

/** One hop's mappings, loaded from the tables the generators write for it.
 * @see ViaVersion MappingDataBase. */
template <int From, int To>
struct MappingDataBase {
    /** The id `To` gives the block `From` calls `id`. A block the hop leaves alone, such as an
     * add-on's, keeps its id. */
    static std::uint32_t getNewBlockStateId(std::uint32_t id)
    {
        const auto &mappings = getBlockStateMappings();
        const auto it = std::ranges::lower_bound(mappings, id, {}, &BlockStateMappings::value_type::first);
        return it != mappings.end() && it->first == id ? it->second : id;
    }

    /** The name `To` gives the item `From` calls `name`, or none for an item `To` lacks. */
    static std::optional<std::string_view> getNewItemName(std::string_view name)
    {
        if constexpr (HasItemMappings<From, To>) {
            if (std::ranges::binary_search(ItemMappings<From, To>::get(), name)) {
                return std::nullopt;
            }
        }
        return name;
    }

    /** Hashes every state of the blocks `getBlockStateUpdates` names, once. */
    static const BlockStateMappings &getBlockStateMappings()
    {
        static const BlockStateMappings mappings = [] {
            BlockStateMappings result;
            for (const auto &update : getBlockStateUpdates<From, To>()) {
                forEachBlock(update, [&](const bp::CompoundTag &states, const bp::CompoundTag &updated) {
                    const auto old_id = computeRawSerializationIdHashForNetwork(update.name, states);
                    const auto new_id = computeRawSerializationIdHashForNetwork(
                        update.rename.empty() ? update.name : update.rename, updated);
                    if (old_id != new_id) {
                        result.emplace_back(old_id, new_id);
                    }
                });
            }
            std::ranges::sort(result);
            return result;
        }();
        return mappings;
    }
};

/** The mappings from `From` to `To`, through the `MappingDataBase` of each hop between them.
 * @see ViaVersion MappingData. */
template <int From, int To>
struct MappingData {
    static std::uint32_t getNewBlockStateId(std::uint32_t id)
    {
        if constexpr (From == To) {
            return id;
        }
        else {
            constexpr int next = step(From, To);
            return MappingData<next, To>::getNewBlockStateId(MappingDataBase<From, next>::getNewBlockStateId(id));
        }
    }

    static std::optional<std::string_view> getNewItemName(std::string_view name)
    {
        if constexpr (From == To) {
            return name;
        }
        else {
            constexpr int next = step(From, To);
            const auto mapped = MappingDataBase<From, next>::getNewItemName(name);
            return mapped ? MappingData<next, To>::getNewItemName(*mapped) : std::nullopt;
        }
    }

    /** Whether some hop between `From` and `To` maps an item. */
    static consteval bool mapsItems()
    {
        if constexpr (From == To) {
            return false;
        }
        else {
            return HasItemMappings<From, step(From, To)> || MappingData<step(From, To), To>::mapsItems();
        }
    }
};

} // namespace endweave
